import org.openqa.selenium.WebDriver;
import org.openqa.selenium.chrome.ChromeDriver;

public class WikipediaTest {
    public static void main(String[] args) {
        // Initialize driver
        WebDriver driver = new ChromeDriver();

        try {
            // Navigate to Wikipedia
            driver.get("https://www.wikipedia.org");

            // Get page title
            String actualTitle = driver.getTitle();

            // Verify title
            if (actualTitle.contains("Wikipedia")) {
                System.out.println("✓ Test PASSED: Title contains Wikipedia");
                System.out.println("Actual title: " + actualTitle);
            } else {
                System.out.println("✗ Test FAILED: Title doesn't contain Wikipedia");
                System.out.println("Expected: Contains 'Wikipedia'");
                System.out.println("Actual: " + actualTitle);
            }

        } finally {
            // Always close browser
            driver.quit();
        }
    }
}
```

**Key Concepts:**
- Try-finally ensures cleanup even if test fails
- driver.getTitle() retrieves page title
- String.contains() for flexible validation
- Always call quit() in finally block

